CREATE OR REPLACE FUNCTION finance_private.guard_unloading_receivable_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid; rid uuid; r public.receivables%rowtype; c public.finance_unloading_charges%rowtype;
begin
 if tg_table_name='receivables' then
  t:=old.tenant_id; rid:=old.id;
 else
  t:=new.tenant_id; rid:=new.receivable_id;
 end if;
 -- Row-first legacy writers must never wait for the finance lock.
 if not pg_try_advisory_xact_lock(hashtextextended(t::text||':finance',0)) then
  raise exception 'finance_unloading_source_busy' using errcode='40001';
 end if;
 if tg_table_name='receivables' then
  if not exists(select 1 from public.finance_unloading_charges where tenant_id=t and receivable_id=rid) then
   if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='DELETE' then raise exception 'finance_unloading_source_immutable' using errcode='55000'; end if;
  if finance_private.consume_unloading_origin_ticket(to_jsonb(old),to_jsonb(new)) then return new;end if;
  if new.id is distinct from old.id or new.tenant_id is distinct from old.tenant_id
    or new.client_id is distinct from old.client_id or new.amount is distinct from old.amount
    or new.client_invoice_id is distinct from old.client_invoice_id
    or new.closing_report_id is distinct from old.closing_report_id
    or to_jsonb(new)->'fiscal_document_id' is distinct from to_jsonb(old)->'fiscal_document_id'
    or to_jsonb(new)->'cte_document_id' is distinct from to_jsonb(old)->'cte_document_id' then
   if not finance_private.consume_unloading_repair_ticket(to_jsonb(old),to_jsonb(new)) then
    raise exception 'finance_unloading_source_immutable' using errcode='55000';end if;
  end if;
  if (new.status in ('cancelled','invoiced') or old.status in ('cancelled','invoiced')) and new.status is distinct from old.status then
   raise exception 'finance_unloading_status_requires_command' using errcode='55000';
  end if;
  return new;
 end if;
 if tg_table_name='finance_unloading_charges' then c:=new;
 else
  select * into c from public.finance_unloading_charges where tenant_id=t and receivable_id=rid;
  if not found then return new; end if;
 end if;
 begin
  select * into r from public.receivables where tenant_id=t and id=rid for share nowait;
 exception when lock_not_available then
  raise exception 'finance_unloading_source_busy' using errcode='40001';
 end;

 if tg_table_name='receivables_payments' then
  declare origin jsonb;begin
   origin:=finance_private.unloading_effective_origin(t,c.id);
   if origin->>'verified' is distinct from 'true' or origin#>>'{effective,status}' is distinct from 'active' then raise exception 'finance_unloading_source_mismatch' using errcode='55000';end if;
   c.supplier_id:=(origin#>>'{effective,supplier_id}')::uuid;c.amount_cents:=(origin#>>'{effective,amount_cents}')::bigint;
  end;
 end if;
 if r.id is null or r.client_id is distinct from c.supplier_id or r.amount is null
   or r.amount::text in ('NaN','Infinity','-Infinity') or r.amount*100 is distinct from c.amount_cents::numeric
   or r.client_invoice_id is not null or r.closing_report_id is not null
   or to_jsonb(r)->>'fiscal_document_id' is not null or to_jsonb(r)->>'cte_document_id' is not null
   or r.status in ('cancelled','invoiced') then
  raise exception 'finance_unloading_source_mismatch' using errcode='55000';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public._guard_receivable_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_total numeric;v_has boolean;begin
 if tg_op='INSERT' then
  if coalesce(new.received_amount,0)<>0 or new.status in('received','partial') then raise exception 'financial_versioned_command_required' using errcode='55000';end if;
  return new;
 end if;
 select exists(select 1 from public.receivables_payments where tenant_id=old.tenant_id and receivable_id=old.id) into v_has; v_has:=v_has or exists(select 1 from finance_private.receivable_balance_adjustment_events where tenant_id=old.tenant_id and receivable_id=old.id); v_has:=v_has or exists(select 1 from finance_private.customer_credit_application_events where tenant_id=old.tenant_id and receivable_id=old.id);
 if tg_op='DELETE' then
  if v_has or old.client_invoice_id is not null or exists(select 1 from public.closing_reports where tenant_id=old.tenant_id and receivable_id=old.id) then
   raise exception 'financial_receivable_history_is_immutable' using errcode='55000';end if;return old;
 end if;
 if (new.id,new.tenant_id) is distinct from (old.id,old.tenant_id) or ((v_has or old.client_invoice_id is not null) and
  (new.amount,new.client_id,new.client_invoice_id,new.closing_report_id) is distinct from (old.amount,old.client_id,old.client_invoice_id,old.closing_report_id)) then
  raise exception 'financial_receivable_identity_is_immutable' using errcode='55000';end if;
 select coalesce(sum(p.amount),0) into v_total from public.receivables_payments p where p.tenant_id=old.tenant_id and p.receivable_id=old.id
  and not exists(select 1 from public.receivable_payment_reversals rv where rv.tenant_id=p.tenant_id and rv.payment_id=p.id) and not exists(select 1 from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id) and not exists(select 1 from public.finance_customer_credits credit where credit.tenant_id=p.tenant_id and credit.payment_id=p.id);
 select net into v_total from public._receivable_ledger_evidence(old.tenant_id,old.id); if coalesce(new.received_amount,0)<>v_total or v_total<0 or v_total>new.amount
  or (new.status='received' and (v_total<=0 or v_total<>new.amount)) or (new.status='partial' and (v_total<=0 or v_total>=new.amount))
  or (new.status in('pending','invoiced','cancelled') and v_total<>0) then
  raise exception 'financial_ledger_requires_reconciliation' using errcode='55000';end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION finance_private.capture_receivable_temporal_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_tenant uuid;source_id uuid;actor uuid:=auth.uid();actor_label text;
begin
 if tg_op='DELETE' then source_tenant:=old.tenant_id;source_id:=old.id;
 else source_tenant:=new.tenant_id;source_id:=new.id;end if;
 if tg_op='UPDATE' and (old.tenant_id,old.id) is distinct from (new.tenant_id,new.id) then
  raise exception 'finance_receivable_temporal_identity_immutable' using errcode='55000';end if;
 -- Capture all successful writers, including workers without an auth actor.
 -- Authorization remains with the original writer; this is not a write API.
 select coalesce(u.raw_user_meta_data->>'full_name',u.email) into actor_label from auth.users u where u.id=actor;
 insert into finance_private.receivable_temporal_versions(tenant_id,receivable_id,operation,old_data,new_data,old_payer_snapshot,new_payer_snapshot,actor_id,actor_name,actor_kind)
 values(source_tenant,source_id,tg_op,case when tg_op<>'INSERT' then to_jsonb(old) end,
  case when tg_op<>'DELETE' then to_jsonb(new) end,
  case when tg_op<>'INSERT' then (select jsonb_build_object('id',c.id,'tenant_id',c.tenant_id,'company_name',c.company_name) from public.clients c where c.tenant_id=source_tenant and c.id=old.client_id) end,
  case when tg_op<>'DELETE' then (select jsonb_build_object('id',c.id,'tenant_id',c.tenant_id,'company_name',c.company_name) from public.clients c where c.tenant_id=source_tenant and c.id=new.client_id) end,
  actor,actor_label,case when actor is null then 'system' else 'authenticated' end);
 return null;
end$function$
